// HRServiceServer is the server API for HRService service.
// All implementations must embed UnimplementedHRServiceServer
// for forward compatibility.
type HRServiceServer interface {
	// ==================== Leave Management ====================
	CreateLeaveRequest(context.Context, *CreateLeaveRequestReq) (*CreateLeaveRequestResp, error)
	GetLeaveRequest(context.Context, *GetLeaveRequestReq) (*GetLeaveRequestResp, error)
	ListLeaveRequests(context.Context, *ListLeaveRequestsReq) (*ListLeaveRequestsResp, error)
	ApproveLeaveRequest(context.Context, *ApproveLeaveRequestReq) (*ApproveLeaveRequestResp, error)
	RejectLeaveRequest(context.Context, *RejectLeaveRequestReq) (*RejectLeaveRequestResp, error)
	CancelLeaveRequest(context.Context, *CancelLeaveRequestReq) (*CancelLeaveRequestResp, error)
	GetLeaveBalance(context.Context, *GetLeaveBalanceReq) (*GetLeaveBalanceResp, error)
	GetEmployeeLeaveBalance(context.Context, *GetEmployeeLeaveBalanceReq) (*GetEmployeeLeaveBalanceResp, error)
	ListLeaveTypes(context.Context, *ListLeaveTypesReq) (*ListLeaveTypesResp, error)
	RecordSickLeave(context.Context, *RecordSickLeaveReq) (*RecordSickLeaveResp, error)
	// ==================== Time Tracking ====================
	ClockIn(context.Context, *ClockInReq) (*ClockInResp, error)
	ClockOut(context.Context, *ClockOutReq) (*ClockOutResp, error)
	StartBreak(context.Context, *StartBreakReq) (*StartBreakResp, error)
	EndBreak(context.Context, *EndBreakReq) (*EndBreakResp, error)
	GetActiveShift(context.Context, *GetActiveShiftReq) (*GetActiveShiftResp, error)
	ListWorkTimeEntries(context.Context, *ListWorkTimeEntriesReq) (*ListWorkTimeEntriesResp, error)
	GetDailySummary(context.Context, *GetDailySummaryReq) (*GetDailySummaryResp, error)
	GetWeeklySummary(context.Context, *GetWeeklySummaryReq) (*GetWeeklySummaryResp, error)
	SubmitTimeCorrection(context.Context, *SubmitTimeCorrectionReq) (*SubmitTimeCorrectionResp, error)
	ApproveTimeCorrection(context.Context, *ApproveTimeCorrectionReq) (*ApproveTimeCorrectionResp, error)
	// Extended time-tracking RPCs (Fall-B)
	CreateManualEntry(context.Context, *CreateManualEntryReq) (*CreateManualEntryResp, error)
	GetTimeBalance(context.Context, *GetTimeBalanceReq) (*GetTimeBalanceResp, error)
	GetTimeAnalytics(context.Context, *GetTimeAnalyticsReq) (*GetTimeAnalyticsResp, error)
	GetTeamTime(context.Context, *GetTeamTimeReq) (*GetTeamTimeResp, error)
	// Week approvals
	GetMyWeekStatus(context.Context, *GetMyWeekStatusReq) (*GetMyWeekStatusResp, error)
	SubmitWeek(context.Context, *SubmitWeekReq) (*SubmitWeekResp, error)
	ApproveWeek(context.Context, *ApproveWeekReq) (*ApproveWeekResp, error)
	RejectWeek(context.Context, *RejectWeekReq) (*RejectWeekResp, error)
	ReopenWeek(context.Context, *ReopenWeekReq) (*ReopenWeekResp, error)
	// Time categories
	ListTimeCategories(context.Context, *ListTimeCategoriesReq) (*ListTimeCategoriesResp, error)
	CreateTimeCategory(context.Context, *CreateTimeCategoryReq) (*CreateTimeCategoryResp, error)
	UpdateTimeCategory(context.Context, *UpdateTimeCategoryReq) (*UpdateTimeCategoryResp, error)
	DeleteTimeCategory(context.Context, *DeleteTimeCategoryReq) (*DeleteTimeCategoryResp, error)
	// Time templates
	ListTimeTemplates(context.Context, *ListTimeTemplatesReq) (*ListTimeTemplatesResp, error)
	CreateTimeTemplate(context.Context, *CreateTimeTemplateReq) (*CreateTimeTemplateResp, error)
	DeleteTimeTemplate(context.Context, *DeleteTimeTemplateReq) (*DeleteTimeTemplateResp, error)
	// Time projects
	ListTimeProjects(context.Context, *ListTimeProjectsReq) (*ListTimeProjectsResp, error)
	CreateTimeProject(context.Context, *CreateTimeProjectReq) (*CreateTimeProjectResp, error)
	// ==================== Absences ====================
	GetAbsenceCalendar(context.Context, *GetAbsenceCalendarReq) (*GetAbsenceCalendarResp, error)
	// ==================== Employee Profiles ====================
	ListEmployees(context.Context, *ListEmployeesReq) (*ListEmployeesResp, error)
	GetEmployee(context.Context, *GetEmployeeReq) (*GetEmployeeResp, error)
	UpdateEmployee(context.Context, *UpdateEmployeeReq) (*UpdateEmployeeResp, error)
	OffboardEmployee(context.Context, *OffboardEmployeeReq) (*OffboardEmployeeResp, error)
	UpdateSelfProfile(context.Context, *UpdateSelfProfileReq) (*UpdateSelfProfileResp, error)
	ListEmployeeDocuments(context.Context, *ListEmployeeDocumentsReq) (*ListEmployeeDocumentsResp, error)
	ListPersonnelDocuments(context.Context, *ListPersonnelDocumentsReq) (*ListPersonnelDocumentsResp, error)
	UploadEmployeeDocument(context.Context, *UploadEmployeeDocumentReq) (*UploadEmployeeDocumentResp, error)
	ListDocumentCategories(context.Context, *ListDocumentCategoriesReq) (*ListDocumentCategoriesResp, error)
	CreateEmployee(context.Context, *CreateEmployeeReq) (*CreateEmployeeResp, error)
	// ==================== Profile Change Requests ====================
	ListProfileChangeRequests(context.Context, *ListProfileChangeRequestsReq) (*ListProfileChangeRequestsResp, error)
	CreateProfileChangeRequest(context.Context, *CreateProfileChangeRequestReq) (*CreateProfileChangeRequestResp, error)
	ApproveProfileChangeRequest(context.Context, *ApproveProfileChangeRequestReq) (*ApproveProfileChangeRequestResp, error)
	RejectProfileChangeRequest(context.Context, *RejectProfileChangeRequestReq) (*RejectProfileChangeRequestResp, error)
	CancelProfileChangeRequest(context.Context, *CancelProfileChangeRequestReq) (*CancelProfileChangeRequestResp, error)
	// ==================== HR Settings ====================
	GetHRSettings(context.Context, *GetHRSettingsReq) (*GetHRSettingsResp, error)
	UpdateHRSettings(context.Context, *UpdateHRSettingsReq) (*UpdateHRSettingsResp, error)
	mustEmbedUnimplementedHRServiceServer()
}

